// Run this script via terminal: `node index.js --force`

// 1. Reading Command Line Arguments
// process.argv is an array. 
// Index 0: Path to Node executable
// Index 1: Path to this script
// Index 2+: The actual arguments typed by the user
const args = process.argv.slice(2);
console.log("Arguments passed:", args); 

// 2. Checking memory usage
const memory = process.memoryUsage();
console.log(`Using ${Math.round(memory.heapUsed / 1024 / 1024)} MB of RAM`);

// 3. Process Information
console.log("Process ID (PID):", process.pid);
console.log("Node Version:", process.version);

// 4. Forcefully Exiting
if (args.includes('--crash')) {
  console.error("Fatal flag passed! Shutting down immediately.");
  process.exit(1); 
}
